function designChanges(before,after){let changes=[];const old=new Map((before?.spaces||[]).map(s=>[s.id,s]));for(const s of after.spaces){const prior=old.get(s.id);if(!prior){changes.push(`${FLOOR_NAMES[s.floor]} floor: ${s.name} added.`);continue;}if(Math.abs(s.area_m2-prior.area_m2)>.01)changes.push(`${s.name} changed from ${prior.area_m2.toFixed(2)} m² to ${s.area_m2.toFixed(2)} m².`);else if(JSON.stringify(s.polygon)!==JSON.stringify(prior.polygon))changes.push(`${s.name} moved on the ${FLOOR_NAMES[s.floor].toLowerCase()} floor.`);old.delete(s.id);}for(const s of old.values())changes.push(`${s.name} removed.`);for(const e of after.furnitureLayout||[]){const prior=(before?.furnitureLayout||[]).find(p=>p.id===e.id);if(JSON.stringify(prior)!==JSON.stringify(e)){const label=currentScene?.editables?.find(i=>i.id===e.id)?.label||e.id.split('/').pop().replaceAll('-',' ');changes.push(`${label}: ${e.dx.toFixed(2)} m right, ${e.dy.toFixed(2)} m rearward, ${e.angle}° rotation from its original placement.`);}}if((before?.furnitureLayout||[]).length&&!(after.furnitureLayout||[]).length)changes.push('Furniture placements reset to their original positions.');if(!!before?.rooftop!==!!after.rooftop)changes.push(after.rooftop?'Roof terrace added with linked stair access and a landing door.':'Roof terrace access removed.');if(before?.brief.exterior_theme===after.brief.exterior_theme&&before?.brief.interior_theme===after.brief.interior_theme&&before?.brief.style===after.brief.style)changes.push('Exterior theme and material palette unchanged.');if(!changes.length)changes.push('Plan geometry unchanged.');$('change-summary-items').replaceChildren();for(const text of changes){const li=document.createElement('li');li.textContent=text;$('change-summary-items').append(li);}$('change-summary').hidden=false;}

