  if(!sessionRefresh)sessionRefresh=(async()=>{const r=await fetch('/api/session');if(!r.ok)throw Error('Reconnect to the local studio and try again.');const fresh=await r.json();if(session.launch_identity&&fresh.launch_identity!==session.launch_identity)throw Error('A different studio is running. Reload this page; your saved draft is kept.');session.token=fresh.token;})().finally(()=>{sessionRefresh=null;});
