// How the plan was made, which positional hints were applied, and the Vastu reading room by room.
function relativeZone(point){let [x,y]=point||[.5,.5],side=x<.34?'left':x>.66?'right':'centre',depth=y<.34?'front':y>.66?'rear':'middle';return depth==='middle'?side:`${depth} ${side}`;}
function placementCard(pl){let audit=pl.placement;if(!audit?.matched?.length)return '';return `<div class="review-card"><h4>Room placement guidance · applied</h4><p>All ${audit.matched.length} requested room position${audit.matched.length===1?' was':'s were'} passed into the planner. Offset is measured against the four-by-four guide (0 is an exact target match); room dimensions remain planner-determined; painted floor assignments are retained.</p><table class="review-table"><tr><th>REQUEST</th><th>SOURCE</th><th>TARGET</th><th>PLANNED SPACE</th><th>OFFSET</th></tr>${audit.matched.map(item=>`<tr><td>${esc(item.label)}</td><td>${item.source==='grid'?'16-cell guide':'Description'}</td><td>${esc(relativeZone(item.target_normalized))}</td><td>${esc(item.space_name)} · ${FLOOR_NAMES[item.floor]} · ${esc(relativeZone(item.actual_normalized))}</td><td>${esc(item.distance_cells)} cells</td></tr>`).join('')}</table></div>`;}
function planCard(r){let pl=currentBuilding?.planning||{},ab=pl.attached_baths,v=r.vastu||{},un=(r.unresolved_requests||[]).filter(Boolean),out='';if(pl.parti)out+=`<div class="review-card"><h4>How the plan was made</h4><p>${esc(pl.parti)} parti, ${esc((pl.footprint_mm||[]).map(x=>(x/1000).toFixed(2)).join(' × '))} m footprint in a ${esc((pl.envelope_mm||[]).map(x=>(x/1000).toFixed(2)).join(' × '))} m buildable area${pl.vastu_mirrored?', mirrored for Vastu':''}.${ab?` Attached baths: ${esc(ab.provided)} of ${esc(ab.requested)} requested.`:''}</p><p>${esc(pl.rules||'')}</p>${pl.variant_mirror_superseded?'<p class="notice">The Mirrored hub variant was superseded because direct room-placement guidance selected the better plan hand.</p>':''}${un.length?`<p><strong>Not fully met:</strong> ${un.map(esc).join(' · ')}</p>`:''}</div>`;out+=placementCard(pl);if(v.status&&v.status!=='off'&&v.rooms?.length)out+=`<div class="review-card"><h4>Vastu reading · ${esc(v.setting)} · ${esc(v.score)}%</h4><table class="review-table"><tr><th>SPACE</th><th>ZONE</th><th>PREFERRED</th><th>READING</th></tr>${v.rooms.map(z=>`<tr><td>${esc(z.space)}</td><td>${esc(z.zone)}</td><td>${esc(z.preferred.join(', '))}</td><td>${esc(z.rating||(z.matches?'preferred':'—'))}</td></tr>`).join('')}</table><p>${esc(v.limitation)}</p></div>`;return out;}
function renderReport(){let r=currentReport;if(!r)return;let c=r.cost,e=r.exterior||{};$('review-content').innerHTML=`<div class="stats"><div class="stat"><span>GROSS FLOOR AREA</span><strong>${esc(r.areas.gross_floor_m2)} m²</strong><span>${esc(r.areas.gross_floor_ft2)} ft² · ${esc(r.areas.ground_coverage_pct)}% ground coverage</span></div><div class="stat"><span>ILLUSTRATIVE COST SCENARIO</span><strong>₹${esc(c.low_lakh)}–${esc(c.high_lakh)} L</strong><span>Editable assumed rates, not market quotations</span></div><div class="stat"><span>EXTERIOR STUDY</span><strong>${esc(e.theme_label||'Current')}</strong><span>${esc(e.assembly_count||0)} assemblies · ${esc(e.landscape_feature_count||0)} landscape features</span></div></div>${!c.within_budget_low?'<div class="notice">Even the low illustrative cost scenario exceeds your budget context. The design has not been declared affordable.</div>':''}<div class="notice">Regulatory: ${esc(r.review.regulatory)} · Structure: ${esc(r.review.structural)} · Accessibility: ${esc(r.review.accessibility)}. These are not approvals.</div><div class="review-card"><h4>What was checked</h4><p>${r.review.checks.map(esc).join(' · ')}</p>${r.review.warnings.map(w=>`<p><strong>${esc(w.code)}</strong> — ${esc(w.message)}</p>`).join('')}</div>${planCard(r)}<div class="review-card"><h4>Space schedule</h4><table class="review-table"><tr><th>SPACE</th><th>FLOOR</th><th>CLEAR AREA</th></tr>${currentBuilding.spaces.map(s=>`<tr><td>${esc(s.name)}</td><td>${FLOOR_NAMES[s.floor]||'Roof'}</td><td>${s.area_m2.toFixed(2)} m²</td></tr>`).join('')}</table></div><div class="review-card"><h4>Timeline scenario</h4><p>Illustrative sequencing, not a contractor commitment.</p>${r.timeline.map(t=>`<div class="timeline-row"><span>${esc(t.phase)}</span><div class="timeline-track"><span style="margin-left:${t.start_week/42*100}%;width:${t.duration_weeks/42*100}%"></span></div><span>${t.duration_weeks} weeks</span></div>`).join('')}</div><div class="review-card"><h4>Sun, soil & site</h4><p>Sun-study elevation ${r.solar.elevation_deg.toFixed(1)}°, azimuth ${r.solar.azimuth_deg.toFixed(1)}°. ${esc(r.solar.method)}. Warm/dusk buttons change the display grade, not the astronomical time.</p><p>${esc(r.structure.soil_warning)}</p><p>Surveyed boundaries, drainage levels, foundation design, loading, lateral stability and reinforcement remain outside this release.</p></div><div class="review-card"><h4>Cost basis & exclusions</h4><p>${esc(c.basis)} Rates: ₹${c.rates_inr_ft2.map(esc).join('–')}/ft², contingency ${esc(c.contingency_pct)}%.</p><p>Excludes ${c.excludes.map(esc).join(', ')}.</p></div><div class="review-card"><h4>Services & quantity truth</h4><p>${r.mep.notes.map(esc).join(' ')}</p><p>${esc(r.quantities.reason)}</p></div>`;}
