const startPage=new FloorForgeStartPage({
 save:()=>projectWorkspace?.save(),
 pause:on=>{if(viewer){viewer.paused=on;viewer.dirty=true;}if(sampleViewerPaused!==null)sampleViewerPaused=on;},
 samples:edit=>sampleGallery.open(edit?'edit':'view'),
 saved:()=>{projectWorkspace?.save();return projectWorkspace?.saved||{};},
 restore:id=>projectWorkspace.switch(id),
 create:async ({title,width,depth,storeys,ai,source})=>{
  if(generationBusy)throw Error('Wait for the current generation to finish.');
  projectWorkspace.save();
  if(!ai){await fetchJSON('/api/ai/clear',{});$('ai-state').textContent='Off';}
  const brief={...session.defaults,title,width_mm:Math.round(width*304.8),depth_mm:Math.round(depth*304.8),storeys,roof_access:true};
  await applyProject({schema:'floorforge.project/0.4',brief,sources:[]});
  $('project-title').textContent=title;projectWorkspace.adopted('new-'+crypto.randomUUID());
  showTab('home');draftState('New project. Set your requirements, then generate its 2D and 3D views. The previous model remains a reference.');
 },
 next:(source,ai)=>{
  if(source==='dxf'){$('import-plan-open').click();return;}
  if(ai){$('plan-dialog').showModal();planEditor.render();$('plan-explore').click();return;}
  if(source==='brief'){$('width').scrollIntoView({block:'center',behavior:'smooth'});$('width').focus();return;}
  projectView('editor');
 }
});
