// Large view: the 3D canvas takes the whole window (true full screen where the browser allows it, a window-filling
// view everywhere else, including iPhone), carrying the view, mode and lighting controls with it.
const stage=document.querySelector('.canvas-wrap'),stageTools=document.querySelector('#home-panel .canvas-tools'),stageToolsHome=stageTools.parentElement;
const viewerActions=stage.querySelector('.canvas-bottom>div');viewerActions.classList.add('viewer-actions');viewerActions.setAttribute('aria-label','Viewer controls');stageTools.append(viewerActions);$('fullscreen').textContent='⤢ Fullscreen';$('tour').textContent='▷ Virtual tour';
function setLargeView(on){if(on===stage.classList.contains('expanded'))return;stage.classList.toggle('expanded',on);document.body.classList.toggle('viewer-expanded',on);if(on){stage.prepend(stageTools);stage.style.setProperty('--tools-h',stageTools.offsetHeight+'px');if(stage.requestFullscreen&&!document.fullscreenElement)stage.requestFullscreen().catch(()=>{});}else{stageToolsHome.insertBefore(stageTools,stage);if(document.fullscreenElement===stage)document.exitFullscreen?.();if(viewer?.focus){viewer.setFocus(false);focusButton(false);}}$('fullscreen').textContent=on?'✕ Exit large view':'⤢ Fullscreen';frameInsets();if(viewer){viewer.resized=true;viewer.dirty=true;}}
// Framing keeps the home clear of the controls laid over the canvas (CSS pixels).
function frameInsets(){if(!viewer)return;const big=stage.classList.contains('expanded'),c=$('scene').getBoundingClientRect();if(big)stage.style.setProperty('--tools-h',stageTools.offsetHeight+'px');let top=big?stageTools.offsetHeight+10:6,bottom=6,right=6;const b=stage.querySelector('.canvas-bottom').getBoundingClientRect(),z=stage.querySelector('.zoom-tools').getBoundingClientRect();if(b.height)bottom=Math.max(bottom,c.bottom-b.top+8);if(z.height){const mid=(z.top+z.bottom)/2;if(mid>c.top+c.height*.3&&mid<c.top+c.height*.7)right=c.right-z.left+8;else bottom=Math.max(bottom,c.bottom-z.top+8);}viewer.frameInsets={top,bottom,left:6,right};}
window.addEventListener('resize',frameInsets);
// Focus: the home alone (street and neighbours set aside), filling the whole screen from the current direction.
function focusButton(on){$('focus').textContent=on?'✕ Exit focus':'◎ Focus';$('focus').classList.toggle('active',on);$('focus').setAttribute('aria-pressed',String(on));}
function setFocus(on){if(!viewer)return;if(on){setLargeView(true);frameInsets();viewer.setFocus(true);focusButton(true);}else{viewer.setFocus(false);focusButton(false);setLargeView(false);}}
$('focus').onclick=()=>setFocus(!viewer?.focus);$('zoom-fit').onclick=()=>viewer?.fitHouse({fill:viewer.focus?.94:.86});
