function setWide(on){workspace.classList.toggle('wide',on);$('brief-toggle').textContent=on?'⇥ Show brief':'⇤ Wider view';$('brief-toggle').setAttribute('aria-pressed',String(on));$('brief-toggle').title=on?'Show the brief panel again':'Hide the brief panel for a wider view of the home';try{localStorage.setItem('ff-wide',on?'1':'0');}catch(e){}if(viewer){viewer.resized=true;viewer.dirty=true;}}
