// Drawing sheets: zoom (buttons, Ctrl/⌘ + scroll, double-click), drag to pan, and a large view.
const sheetHolder=document.querySelector('.drawing-holder'),sheetImage=$('drawing-image');let sheetZoom=1,sheetDrag=null;
function zoomSheet(level,cx,cy){const r=sheetHolder.getBoundingClientRect();cx=cx??r.left+r.width/2;cy=cy??r.top+r.height/2;const fx=(sheetHolder.scrollLeft+cx-r.left)/Math.max(1,sheetHolder.scrollWidth),fy=(sheetHolder.scrollTop+cy-r.top)/Math.max(1,sheetHolder.scrollHeight);sheetZoom=Math.min(8,Math.max(1,level));if(sheetZoom<1.05)sheetZoom=1;sheetHolder.classList.toggle('zoomed',sheetZoom>1);sheetImage.style.width=sheetZoom>1?sheetZoom*100+'%':'';$('sheet-fit').textContent=sheetZoom>1?Math.round(sheetZoom*100)+'%':'Fit';sheetHolder.scrollLeft=fx*sheetHolder.scrollWidth-(cx-r.left);sheetHolder.scrollTop=fy*sheetHolder.scrollHeight-(cy-r.top);}
$('sheet-zoom-in').onclick=()=>zoomSheet(sheetZoom*1.5);$('sheet-zoom-out').onclick=()=>zoomSheet(sheetZoom/1.5);$('sheet-fit').onclick=()=>zoomSheet(1);
sheetHolder.addEventListener('wheel',e=>{if(!(e.ctrlKey||e.metaKey))return;e.preventDefault();zoomSheet(sheetZoom*(e.deltaY<0?1.2:1/1.2),e.clientX,e.clientY);},{passive:false});
sheetImage.addEventListener('dblclick',e=>zoomSheet(sheetZoom>1?1:2.5,e.clientX,e.clientY));
sheetHolder.addEventListener('pointerdown',e=>{if(sheetZoom<=1||e.button!==0||e.target.closest('button'))return;sheetDrag={x:e.clientX,y:e.clientY,l:sheetHolder.scrollLeft,t:sheetHolder.scrollTop,id:e.pointerId};sheetHolder.setPointerCapture(e.pointerId);sheetHolder.classList.add('panning');});
sheetHolder.addEventListener('pointermove',e=>{if(!sheetDrag||e.pointerId!==sheetDrag.id)return;sheetHolder.scrollLeft=sheetDrag.l-(e.clientX-sheetDrag.x);sheetHolder.scrollTop=sheetDrag.t-(e.clientY-sheetDrag.y);});
const endSheetDrag=()=>{sheetDrag=null;sheetHolder.classList.remove('panning');};sheetHolder.addEventListener('pointerup',endSheetDrag);sheetHolder.addEventListener('pointercancel',endSheetDrag);
function setSheetLarge(on){sheetHolder.classList.toggle('expanded',on);document.body.classList.toggle('viewer-expanded',on||stage.classList.contains('expanded'));$('sheet-close').hidden=!on;$('sheet-large').textContent=on?'✕ Exit large view':'⤢ Large view';if(on&&sheetHolder.requestFullscreen&&!document.fullscreenElement)sheetHolder.requestFullscreen().catch(()=>{});if(!on&&document.fullscreenElement===sheetHolder)document.exitFullscreen?.();}
$('sheet-large').onclick=()=>setSheetLarge(!sheetHolder.classList.contains('expanded'));$('sheet-close').onclick=()=>setSheetLarge(false);
$('sheet-select').addEventListener('change',()=>zoomSheet(1));

document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement)return;if(stage.classList.contains('expanded'))setLargeView(false);if(sheetHolder.classList.contains('expanded'))setSheetLarge(false);});
