async function useSampleProject(sample){
 if(generationBusy)throw Error('Wait for the current generation to finish, then open the sample.');
 projectWorkspace?.save();
 const project=await fetchJSON(sample.baseUrl+'project.floorforge.json');
 const intent=await fetchJSON('/api/intent',project);
 if(intent.planHash!==sample.planHash)throw Error('This sample project does not match its generated model.');
 if(!sampleBackup){const previous={...projectSnapshot(),workspaceId:projectWorkspace?.active};localStorage.setItem('floorforge-project-before-sample',JSON.stringify(previous));sampleBackup=previous;}
 $('sample-return').hidden=false;
 await applyProject(project);
 const resolved=await fetchJSON('/api/intent',collect());
 if(resolved.planHash!==sample.planHash)throw Error('The sample settings changed while loading. Your previous project is kept.');
 await loadBuild('sample:'+sample.id,{hash:sample.planHash,revision:draftRevision});
 showTab('home');viewer?.setMode('dollhouse');setModeButtons('dollhouse');viewer?.setFloor(0);$('floor').value='0';
 draftState(sample.title+' · ready to edit. Your previous project is kept.',true);localStorage.setItem('floorforge-draft-v1',JSON.stringify(collect()));
 projectWorkspace?.adopted(sample.id);startPage.enter();
 toast('Sample opened. Change its settings or edit rooms. Back to my previous project restores your work.',9000);
}
$('sample-return').onclick=async()=>{
 if(!sampleBackup||generationBusy)return;
 const button=$('sample-return');button.disabled=true;
 try{
  projectWorkspace?.save();
  localStorage.setItem('floorforge-last-sample-work',JSON.stringify(collect()));
  const saved=sampleBackup;await applyProject(saved.project);await loadBuild(saved.build);showTab('home');draftState(saved.message,saved.current);if(projectWorkspace){projectWorkspace.active=saved.workspaceId||'current-project';projectWorkspace.save();}
  localStorage.removeItem('floorforge-project-before-sample');sampleBackup=null;button.hidden=true;localStorage.setItem('floorforge-draft-v1',JSON.stringify(collect()));toast('Your previous project and 3D view are restored.');
 }catch(e){toast('Could not restore the previous view. Its saved project is still kept. '+e.message);}
 finally{button.disabled=false;}
};

function projectSnapshot(){return {project:collect(),build:activeBuild,message:$('draft-state').textContent,current:!draftStale};}
async function restoreWorkspace(saved){if(generationBusy)throw Error('Wait for generation to finish.');await applyProject(saved.project);await loadBuild(saved.build);draftState(saved.message,saved.current);showTab('home');localStorage.setItem('floorforge-draft-v1',JSON.stringify(collect()));}
function projectView(view){
 for(const id of ['project-specs-dialog','plan-dialog','grid-dialog','room-board-dialog'])if($(id).open)$(id).close();
 if(view==='editor'){
  $('plan-dialog').querySelector('.overline').textContent='ROOM PLANNER · '+$('adv-title').value;
  if($('plan-mode').value==='custom'&&planEditor.plan?.floors.some(f=>f.rooms.length)){$('plan-dialog').showModal();planEditor.render();}
  else roomBoard.open();return;
 }
 if(view==='cells'){$('grid-open').click();return;}
 if(view==='2d'){showTab('drawings');$('sheet-select').value='A-101';showSheet();return;}
 if(view==='3d'){showTab('home');viewer?.setMode('dollhouse');setModeButtons('dollhouse');return;}
 if(view==='specs')showProjectSpecifications();
}
function showProjectSpecifications(){
 const b=currentBuilding;if(!b)return;const v=b.brief,feet=n=>(n/304.8).toFixed(2).replace(/\.00$/,''),metres=n=>(n/1000).toFixed(2),side=deg=>compassName((deg+360)%360);
 const frontEdge=(b.footprint||[]).filter(p=>p[1]<=Math.min(...(b.footprint||[]).map(p=>p[1]))+150),plotXs=(b.plot||[]).map(p=>p[0]);
 const frontLeft=frontEdge.length?Math.min(...frontEdge.map(p=>p[0]))-Math.min(...plotXs):v.left_mm,frontRight=frontEdge.length?Math.max(...plotXs)-Math.max(...frontEdge.map(p=>p[0])):v.right_mm;
 const partialLanes=b.planning?.custom&&(frontLeft>v.left_mm+100||frontRight>v.right_mm+100)?`<p><strong>Side lanes beside the front rooms</strong><br>Left ${feet(frontLeft)} ft / right ${feet(frontRight)} ft<br><small>These lanes end where the rear wings widen. Minimum clearances below describe the widest parts of the house.</small></p>`:'';
 $('project-specs-title').textContent=v.title;
 const cellMapping=currentProject.customPlan?'The room editor, 2D drawings and 3D use the same authored polygons. The 16-cell guide is a broad placement summary; small rooms can share a cell, so it is not an exact floor plan. Editing a guide selects a different generation input.':'The 2D and 3D describe the generated home. Open the room editor to create an editable arrangement.';
 $('project-specs-content').innerHTML=`<p class="notice">${draftStale?'These are the last generated design’s measurements. Your draft has edits; generate to update every view.':'These specifications match the displayed 2D and 3D design.'}</p><div class="spec-facts"><p><strong>Plot</strong><br>${feet(v.width_mm)} × ${feet(v.depth_mm)} ft<br>${metres(v.width_mm)} × ${metres(v.depth_mm)} m</p><p><strong>Road / front</strong><br>${esc(side(v.road_bearing_deg))} · G+${b.storeys-1}<br>${b.rooftop?'Stairs continue to roof terrace':'No roof access'}</p><p><strong>Front / rear setbacks</strong><br>${feet(v.front_mm)} / ${feet(v.rear_mm)} ft</p>${partialLanes}<p><strong>Minimum left / right clearance</strong><br>${esc(side(v.road_bearing_deg+90))} ${feet(v.left_mm)} ft / ${esc(side(v.road_bearing_deg-90))} ${feet(v.right_mm)} ft</p><p><strong>Buildable envelope</strong><br>${feet(v.width_mm-v.left_mm-v.right_mm)} × ${feet(v.depth_mm-v.front_mm-v.rear_mm)} ft</p><p><strong>Floor-to-floor height</strong><br>${metres(v.floor_height_mm)} m · ${feet(v.floor_height_mm)} ft</p></div><p>${esc(cellMapping)}</p><p class="spec-note">${esc(currentProject.notes||'')}</p><div class="spec-table-scroll"><table class="spec-table"><thead><tr><th>Floor / room</th><th>Clear size · metres</th><th>Clear size · feet</th><th>Area</th><th></th></tr></thead><tbody>${b.spaces.map(r=>{const pts=r.clear||r.polygon,x=pts.map(p=>p[0]),y=pts.map(p=>p[1]),w=Math.max(...x)-Math.min(...x),d=Math.max(...y)-Math.min(...y);return `<tr><td>${r.floor===b.storeys?'Roof':FLOOR_NAMES[r.floor]} · ${esc(r.name)}</td><td>${metres(w)} × ${metres(d)}</td><td>${feet(w)} × ${feet(d)}</td><td>${r.area_m2.toFixed(2)} m²</td><td><button type="button" class="quiet" data-spec-room="${esc(r.id)}" data-spec-floor="${r.floor}">Show in 3D</button></td></tr>`;}).join('')}</tbody></table></div><p class="micro">Sizes are clear inside-wall bounding dimensions; irregular rooms and roof terraces use their polygon area. All exports carry plan hash ${esc(b.planHash)}.</p><a class="secondary" href="${base}drawings.pdf" target="_blank" rel="noopener">Download dimensioned drawing set</a>`;
 $('project-specs-content').querySelectorAll('[data-spec-room]').forEach(button=>button.onclick=()=>{projectView('3d');viewer.setFloor(Number(button.dataset.specFloor));$('floor').value=button.dataset.specFloor;viewer.highlightRoom?.(button.dataset.specRoom);});
 $('project-specs-dialog').showModal();
}

// Import runs locally through the exact-plan compiler, never the automatic arranger.
let planImportBusy=false;
$('import-plan-open').onclick=()=>$('import-plan-dialog').showModal();
$('import-plan-close').onclick=()=>$('import-plan-dialog').close();
$('import-plan-choose').onclick=()=>{if(generationBusy||planImportBusy){toast('Wait for the current generation or import to finish.');return;}$('import-plan-file').click();};
$('import-plan-file').onchange=async event=>{
 const file=event.target.files[0];event.target.value='';if(!file)return;
 const result=$('import-plan-result');
 if(generationBusy||planImportBusy){result.textContent='Wait for the current generation or import to finish.';return;}
 planImportBusy=true;$('import-plan-choose').disabled=true;const revision=draftRevision;
 result.textContent='Reading the drawing and checking its geometry…';
 try{
  if(!file.name.toLowerCase().endsWith('.dxf')||file.size>750000)throw Error('Choose an ASCII .dxf file up to 750 KB.');
  const imported=await fetchJSON('/api/plan/import-dxf',{filename:file.name,text:await file.text()});
  if(revision!==draftRevision||generationBusy)throw Error('The current project changed during import. Choose the file again when ready.');
  localStorage.setItem('floorforge-draft-before-dxf-import',JSON.stringify(collect()));
  projectWorkspace?.save();await applyProject(imported.project);planEditor.setDetail(true);
  projectWorkspace?.adopted('import-'+crypto.randomUUID());
  result.replaceChildren();
  const summary=document.createElement('p');summary.textContent=`Imported ${imported.roomCount} rooms and ${imported.openingCount} openings. Your previous draft is saved in My projects.`;result.append(summary);
  for(const note of imported.notes){const p=document.createElement('p');p.className='micro';p.textContent=note;result.append(p);}
  if(!imported.valid){
   const p=document.createElement('p');p.className='notice';p.textContent='3D generation is blocked: '+imported.issue.message;result.append(p);
   const button=document.createElement('button');button.textContent='Review imported plan';button.className='secondary';button.onclick=()=>{$('import-plan-dialog').close();$('plan-dialog').showModal();planEditor.presentErrors(imported.issue.details?.errors||[],imported.issue.message);planEditor.render();};result.append(button);
  }else{
   $('import-plan-dialog').close();toast('DXF imported. Generating its exact geometry. Reopen Import 2D floor plan to read assumptions.',9000);
   planEditor.preparedGeneration=true;await generate();
  }
 }catch(error){result.textContent=formatError(error);}
 finally{planImportBusy=false;$('import-plan-choose').disabled=false;}
};
